import{_ as t,o as e,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const l="/assets/collection-root.CzqozG4O.jpg",_=JSON.parse('{"title":"📂 合集解析结果不完整","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/collection-download-error.md","filePath":"troubleshooting/collection-download-error.md","lastUpdated":1793618458000}'),i={name:"troubleshooting/collection-download-error.md"};function n(s,o,c,d,p,h){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="📂-合集解析结果不完整" tabindex="-1">📂 合集解析结果不完整 <a class="header-anchor" href="#📂-合集解析结果不完整" aria-label="Permalink to &quot;📂 合集解析结果不完整&quot;">​</a></h1><h2 id="🔍-选择解析范围" tabindex="-1">🔍 选择解析范围 <a class="header-anchor" href="#🔍-选择解析范围" aria-label="Permalink to &quot;🔍 选择解析范围&quot;">​</a></h2><p>粘贴合集成员的 BV / AV 播放地址后，应用会检测所属合集。如果发现合集，会显示「选择解析范围」：</p><ul><li><strong>当前视频（全部分 P）</strong>：仅列出当前投稿的所有分 P。</li><li><strong>整个合集</strong>：列出该合集的成员及成员内的各个分 P。</li><li><strong>取消</strong>：不开始解析。</li></ul><p>例如，<code>https://www.bilibili.com/video/BV17zDWYwEj8/?p=2</code> 属于「测试」合集。验证时，选择当前视频得到 <strong>2 个分 P</strong>；选择整个合集得到 <strong>2 个 BV、3 个条目</strong>。链接中的 <code>p=2</code> 不会把「当前视频（全部分 P）」限制成一项。合集内容可能随后续编辑发生变化。</p><p>合集入口地址直接解析指定合集。没有所属合集信息的普通投稿直接解析当前 BV；视频标题里写着「合集」不代表它属于 B 站的合集。</p><h2 id="💡-没有出现范围选择-或结果不完整时" tabindex="-1">💡 没有出现范围选择，或结果不完整时 <a class="header-anchor" href="#💡-没有出现范围选择-或结果不完整时" aria-label="Permalink to &quot;💡 没有出现范围选择，或结果不完整时&quot;">​</a></h2><ol><li><strong>确认应用和内核已更新。</strong> 此交互需要应用中的合集检测功能及 uiya-yutto 0.3.5 或更新内核。便携版需使用内置新版程序和内核的发行包；源码 / uv 环境需同步依赖。</li><li><strong>更新后完全退出并重新打开应用。</strong> 已启动的 yutto server 会继续使用原先加载的内核，自定义 Python 环境也需要升级内核。</li><li><strong>查看控制台。</strong> 合集检测失败时，应用会提示并继续解析当前视频；成员失效、访问权限和网络错误也可能导致部分条目失败。</li></ol><h2 id="✅-使用合集入口排查" tabindex="-1">✅ 使用合集入口排查 <a class="header-anchor" href="#✅-使用合集入口排查" aria-label="Permalink to &quot;✅ 使用合集入口排查&quot;">​</a></h2><p>点击播放页的合集名称，在 UP 主空间打开合集，再复制合集入口地址解析。</p><p><img src="'+l+'" alt="collection-root"></p><p>合集入口通常形如 <code>https://space.bilibili.com/&lt;UP主ID&gt;/lists/&lt;合集ID&gt;?type=season</code>。这种地址明确指定合集，不依赖当前视频详情中的合集信息。</p><p>如果合集入口可以完整解析，而成员播放页没有显示范围选择，请反馈两个地址、应用 / 内核版本和控制台错误。</p>',13)])])}const u=t(i,[["render",n]]);export{_ as __pageData,u as default};
